package com.example.starter.firmware.domain;

/**
 * 兼容判定结果：GRANTED 模块全部满足直接下发；EXEMPTION 有模块依靠有效豁免放行后下发；
 * BLOCKED 存在缺失或低版本模块，阻断下发且不创建任务。
 */
public enum CompatibilityOutcome {
    GRANTED,
    EXEMPTION,
    BLOCKED
}

package com.example.starter.firmware.domain;

/**
 * 任务下发途径：DIRECT 全部所需模块由设备直接满足；EXEMPTION 至少一个模块依靠发布单有效豁免放行。
 */
public enum GrantedVia {
    DIRECT,
    EXEMPTION
}

package com.example.starter.firmware.domain;

/**
 * 模块阻断原因：MISSING 设备清单中缺失该模块（设备版本为 null）；
 * VERSION_TOO_LOW 设备模块版本低于最低要求。
 */
public enum ModuleBlockReason {
    MISSING,
    VERSION_TOO_LOW
}

package com.example.starter.firmware.domain;

/**
 * 固件直接声明的模块需求（兼容矩阵的一行）。
