package com.example.starter.firmware.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 设备登记请求。deviceGroup 为可选设备组名，登记后不可修改；
 * 不传或为 null 表示不属于任何组，不适用任何模块豁免。
 */
public record RegisterDeviceRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String deviceId,
        @NotBlank @Size(max = 64) String model,
        @NotBlank @Size(max = 64) String currentVersion,
        @Min(0) @Max(99) int bucketNo,
        @Size(max = 64) String deviceGroup) {

    /**
     * 兼容旧调用方：不指定设备组。
     */
    public RegisterDeviceRequest(String requestId, String deviceId, String model, String currentVersion,
                                 int bucketNo) {
        this(requestId, deviceId, model, currentVersion, bucketNo, null);
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.Device;

/**
 * 设备视图。deviceGroup 为设备组名，不属于任何组时为 null（null 语义稳定）。
 */
public record DeviceView(String deviceId, String model, String currentVersion, int bucketNo,
                         String deviceGroup) {

    public static DeviceView of(Device device) {
        return new DeviceView(device.deviceId(), device.model(), device.currentVersion(), device.bucketNo(),
                device.deviceGroup());
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.CompatibilityOutcome;
import com.example.starter.firmware.domain.ReleaseOrder;
import com.example.starter.firmware.domain.RolloutTask;

import java.util.List;

/**
 * 投放任务视图。任务行固化的兼容证据随任务返回；已存在任务再次拉取时展示其下发时版本，
 * 设备后续上报或矩阵修订均不改写这些字段。
 */
public record TaskView(long taskId, long releaseId, String deviceId, String status,
                       String fromVersion, String toVersion, int matrixVersion, int exemptionVersion,
                       String grantedVia, List<DeviceModulesView.Item> deviceModules) {

    public static TaskView of(RolloutTask task, ReleaseOrder order) {
        return new TaskView(task.id(), task.releaseId(), task.deviceId(), task.status().name(),
                order.fromVersion(), order.toVersion(), task.matrixVersion(), task.exemptionVersion(),
                task.grantedVia().name(), SnapshotJson.parseItems(task.deviceModulesJson()));
    }

    /**
     * 历史兼容：无模块信息时的判定结果名（DIRECT 对应 GRANTED）。
     */
    public static String outcomeNameOf(RolloutTask task) {
        return task.grantedVia().name().equals("EXEMPTION")
                ? CompatibilityOutcome.EXEMPTION.name()
                : CompatibilityOutcome.GRANTED.name();
    }
}

