    @Test
    void 设备模块上报_全量替换_非法与重复422_不改固件版本() throws Exception {
        registerDevice("r0", "d1", "m1", "1.0.0", 1, null);
        reportModules("d1", "r1", "modA", "1.0", "sha-a1", "modB", "2.0", "sha-b1");
